import { test } from '@playwright/test';

import { loginAs } from '../bazis';

import { PRODUCT } from './product';

test('manager-cannot-save-an-empty-title', async ({ page }) => {
  const app = await loginAs(page, PRODUCT, 'manager');
  await test.step('open: task-list', async () => {
    await app.open('task-list');
  });
  await test.step('action: create', async () => {
    await app.action('create');
  });
  await test.step('fill: {title: \'\'}', async () => {
    await app.fill({ title: '' });
  });
  await test.step('submit', async () => {
    await app.submit();
  });
  await test.step('expect: {error: title}', async () => {
    await app.expectError('title');
  });
  await test.step('fill: {title: Plan the week}', async () => {
    await app.fill({ title: 'Plan the week' });
  });
  await test.step('submit', async () => {
    await app.submit();
    await app.expectScreen('task-card');
  });
  await test.step('expect: {screen: task-card, status: draft}', async () => {
    await app.expectScreen('task-card');
    await app.expectStatus('draft');
  });
  await test.step('fill: {title: \'\'}', async () => {
    await app.action('edit');
    await app.fill({ title: '' });
  });
  await test.step('submit', async () => {
    await app.submit();
  });
  await test.step('expect: {error: title}', async () => {
    await app.expectError('title');
  });
  await test.step('fill: {title: Plan the next week}', async () => {
    await app.fill({ title: 'Plan the next week' });
  });
  await test.step('submit', async () => {
    await app.submit();
  });
  await test.step('transit: start', async () => {
    await app.transit('start');
  });
  await test.step('expect: {status: in_progress, field_readonly: title}', async () => {
    await app.expectStatus('in_progress');
    await app.expectFieldReadonly('title');
  });
});
